(172, array['20-70mm','70-200mm'], $q$Travel day; the zooms for the river at dusk once you're in.$q$),
(173, array['20-70mm','70-200mm','35mm'], $q$Two rafts: strap on, a plastic bag ready. Zooms all day; the 35 for Xingping's lanes and dinner.$q$),
(174, array['20-70mm','70-200mm'], $q$Goodbye morning, then the rooftop at dusk on the zooms.$q$),
(175, array['20-70mm','70-200mm'], $q$Laozhai Hill at sunrise if you're up (headlamp), then the river trail: both zooms.$q$),
(177, array['20-70mm','70-200mm'], $q$Driver day: the zooms. Yulong Bridge first, while the water is still.$q$),
